import { z } from "zod";
import raw from "./season-2026.data.json";

/**
 * 2026 calendar, generated by `npm run sync:season` from OpenF1 (meetings/sessions) and Jolpica-F1
 * (rounds/circuits). The JSON is validated at load so a bad regeneration fails loudly instead of
 * rendering a wrong schedule. All session times are stored in UTC (ISO 8601).
 */

export const SESSION_TYPES = ["PRACTICE", "SPRINT_QUALIFYING", "SPRINT", "QUALIFYING", "RACE", "TESTING"] as const;
export type SessionType = (typeof SESSION_TYPES)[number];

const sessionSchema = z.object({
  openf1SessionKey: z.number().int(),
  name: z.string(),
  type: z.enum(SESSION_TYPES),
  start: z.iso.datetime(),
  end: z.iso.datetime(),
  cancelled: z.boolean(),
});

const eventSchema = z.object({
  id: z.string(),
  season: z.number().int(),
  round: z.number().int().nullable(),
  openf1MeetingKey: z.number().int(),
  name: z.string(),
  officialName: z.string(),
  jolpicaRaceName: z.string().nullable(),
  status: z.enum(["scheduled", "cancelled"]),
  format: z.enum(["standard", "sprint", "testing"]),
  startDate: z.string(),
  endDate: z.string(),
  gmtOffset: z.string(),
  circuit: z.object({
    id: z.string(),
    openf1CircuitKey: z.number().int(),
    name: z.string(),
    shortName: z.string(),
    locality: z.string(),
    country: z.string(),
    type: z.string().nullable(),
    lat: z.number().nullable(),
    long: z.number().nullable(),
    timeZone: z.string(),
  }),
  sessions: z.array(sessionSchema),
});

const seasonSchema = z.object({
  season: z.number().int(),
  generatedAt: z.iso.datetime(),
  sources: z.array(z.string()),
  warnings: z.array(z.string()),
  events: z.array(eventSchema),
});

export type ScheduleSession = z.infer<typeof sessionSchema>;
export type ScheduleEvent = z.infer<typeof eventSchema>;
export type SeasonSchedule = z.infer<typeof seasonSchema>;

export const SEASON_2026: SeasonSchedule = seasonSchema.parse(raw);

/** Championship rounds only (excludes testing and cancelled events), in round order. */
export const ROUNDS_2026: ScheduleEvent[] = SEASON_2026.events
  .filter((e) => e.round !== null && e.status === "scheduled")
  .sort((a, b) => (a.round ?? 0) - (b.round ?? 0));

export function eventById(id: string): ScheduleEvent | undefined {
  return SEASON_2026.events.find((e) => e.id === id);
}

export function eventByRound(round: number): ScheduleEvent | undefined {
  return ROUNDS_2026.find((e) => e.round === round);
}

export function findSession(sessionKey: number): { event: ScheduleEvent; session: ScheduleSession } | undefined {
  for (const event of SEASON_2026.events) {
    const session = event.sessions.find((s) => s.openf1SessionKey === sessionKey);
    if (session) return { event, session };
  }
  return undefined;
}

export type ScheduleState = "upcoming" | "in-window" | "completed" | "cancelled";

/**
 * Where a session sits relative to its *published schedule*. "in-window" means the clock is inside the
 * scheduled start/end times — it is not evidence that live data exists.
 */
export function scheduleState(session: Pick<ScheduleSession, "start" | "end" | "cancelled">, now: Date = new Date()): ScheduleState {
  if (session.cancelled) return "cancelled";
  const t = now.getTime();
  if (t < Date.parse(session.start)) return "upcoming";
  if (t <= Date.parse(session.end)) return "in-window";
  return "completed";
}

/** Most recent session whose scheduled end has passed (candidates for historical data). */
export function latestCompletedSession(now: Date = new Date()): { event: ScheduleEvent; session: ScheduleSession } | undefined {
  let best: { event: ScheduleEvent; session: ScheduleSession } | undefined;
  for (const event of SEASON_2026.events) {
    if (event.status === "cancelled") continue;
    for (const session of event.sessions) {
      if (scheduleState(session, now) !== "completed") continue;
      if (!best || session.end > best.session.end) best = { event, session };
    }
  }
  return best;
}

export function nextSession(now: Date = new Date()): { event: ScheduleEvent; session: ScheduleSession } | undefined {
  let best: { event: ScheduleEvent; session: ScheduleSession } | undefined;
  for (const event of SEASON_2026.events) {
    if (event.status === "cancelled") continue;
    for (const session of event.sessions) {
      const st = scheduleState(session, now);
      if (st !== "upcoming" && st !== "in-window") continue;
      if (!best || session.start < best.session.start) best = { event, session };
    }
  }
  return best;
}

export const SESSION_TYPE_LABEL: Record<SessionType, string> = {
  PRACTICE: "Practice",
  SPRINT_QUALIFYING: "Sprint Qualifying",
  SPRINT: "Sprint",
  QUALIFYING: "Qualifying",
  RACE: "Grand Prix",
  TESTING: "Testing",
};
